// Đoạn cấu hình trích xuất từ composer.json của một Laravel package
{
    "name": "enterprise/payment-sdk",
    "description": "Enterprise Payment SDK with Laravel Auto-Discovery",
    "type": "library",
    "require": {
        "php": "^8.2",
        "guzzlehttp/guzzle": "^7.8"
    },
    "autoload": {
        "psr-4": {
            "Enterprise\\PaymentSDK\\": "src/"
        }
    },
    "extra": {
        "laravel": {
            "providers": [
                "Enterprise\\PaymentSDK\\Providers\\PaymentServiceProvider"
            ],
            "aliases": {
                "PaymentGateway": "Enterprise\\PaymentSDK\\Facades\\PaymentGateway"
            }
        }
    }
}

// Quy trình tối ưu hóa trong Dockerfile CI/CD:
// RUN composer install --no-dev --no-interaction --prefer-dist --optimize-autoloader --classmap-authoritative
